#include <stdio.h>

void convert(long long n, char *text, int *length) {
    if (n >= 10) convert(n / 10, text, length);
    text[(*length)++] = (char)('0' + n % 10);
}

int main(void) {
    long long n;
    char text[32];
    int length = 0;
    scanf("%lld", &n);
    if (n < 0) { text[length++] = '-'; n = -n; }
    convert(n, text, &length);
    text[length] = '\0';
    puts(text);
    return 0;
}
